function validate([secret, guess]) {
  if (typeof secret !== 'string' || typeof guess !== 'string') return 'secret and guess must be strings.';
  if (secret.length < 1 || secret.length > 1000) return 'secret needs 1 to 1000 digits.';
  if (guess.length !== secret.length) return 'guess must be as long as secret.';
  if (!/^[0-9]+$/.test(secret) || !/^[0-9]+$/.test(guess)) return 'Both strings may contain digits only.';
  return null;
}

