function generate(rand, size) {
  const n = size === 'large' ? 1000 - Math.floor(rand() * 3) : 1 + Math.floor(rand() * 8);
  const alphabet = size === 'large' ? 10 : [2, 3, 10][Math.floor(rand() * 3)];
  const digit = () => String(Math.floor(rand() * alphabet));
  let secret = '';
  for (let i = 0; i < n; i++) secret += digit();
  let guess = '';
  const mode = rand();
  for (let i = 0; i < n; i++) {
    if (mode < 0.3) guess += rand() < 0.5 ? secret[i] : digit();
    else if (mode < 0.5) guess += secret[n - 1 - i];
    else guess += digit();
  }
  return [secret, guess];
}
